document.querySelectorAll(".navbar-nav .nav-link").forEach(function(e){e.addEventListener("click",function(){var e=document.getElementById("main-navigation");e&&e.classList.contains("show")&&bootstrap.Collapse.getOrCreateInstance(e).hide()})}),document.querySelectorAll('a.scroll[href*="#"]:not([href="#"])').forEach(function(o){o.addEventListener("click",function(e){var t;location.hostname===o.hostname&&location.pathname.replace(/^\//,"")===o.pathname.replace(/^\//,"")&&o.hash&&(t=decodeURIComponent(o.hash.slice(1)),t=document.getElementById(t)||document.getElementsByName(t)[0])&&(e.preventDefault(),window.scrollTo({top:t.getBoundingClientRect().top+window.scrollY-70,behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"}))})}),document.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(function(e){new bootstrap.Tooltip(e)});